        long[] board = Arrays.copyOf(startArr, 14);
        long n = board[i];
        board[i] = 0;
        if (n == 0) {
            return 0;
        }
        long addToAll = n / 14;
        n = n % 14;
        for (int j = 0; j < 14; j++) {
            board[j] += addToAll;
        }
        int currentIdx = i;
        while (n != 0) {
            currentIdx++;
            if (currentIdx == 14) {
                currentIdx = 0;
            }
            board[currentIdx]++;
            n--;
        }
        long result = 0;
        for (int j = 0; j < 14; j++) {
            if (board[j] % 2 == 0) {
                result += board[j];
            }
        }
        return result;
    }
}

